from pathlib import Path
import json
rows=json.load(open('/app/poster/top20.json'))
# categorize
claude={"shanraisshan/claude-code-best-practice","affaan-m/everything-claude-code","thedotmack/claude-mem","ultraworkers/claw-code","openclaw/openclaw"}
agent_fw={"NousResearch/hermes-agent","JuliusBrussee/caveman","addyoosmani/agent-skills","rtk-ai/rtk","garrytan/gstack","multica-ai/multica","OpenBMB/VoxCPM"}
ai_utils={"microsoft/markitdown","forrestchang/andrej-karpathy-skills","shiyu-coder/Kronos"}
design_tools={"VoltAgent/awesome-design-md","safishamsi/graphify"}
prod_tools={"obra/superpowers","MemPalace/mempalace","santifer/career-ops"}
other=set(r['repo'] for r in rows) - claude-agent_fw-ai_utils-design_tools-prod_tools
print('other',other)

def cat(repo):
  if repo in claude: return ('CLAUDE', 'Claude Code')
  if repo in agent_fw: return ('AGENT', 'Agents')
  if repo in ai_utils: return ('UTIL', 'AI Utilities')
  if repo in design_tools: return ('DESIGN', 'AI Design')
  if repo in prod_tools: return ('PROD', 'Dev/Productivity')
  return ('OTHER','Other')

# Build latex lines
lines=[]
for r in rows:
  short=r['repo'].split('/')[-1]
  owner=r['repo'].split('/')[0]
  tag, taglabel = cat(r['repo'])
  # trend map
  trend=r['trend']
  if trend=='—': trend_str='\textcolor{white!70}{—}'
  elif trend=='▲': trend_str='\textcolor{greenaccent}{\large$\blacktriangle$}'
  elif trend=='▼': trend_str='\textcolor{amberaccent}{\large$\blacktriangledown$}'
  else: trend_str='\textcolor{blueaccent}{\bfseries N}'
  stars=f"+{r['stars']:,}"
  lines.append({
    'rank':r['rank'],
    'trend':trend_str,
    'repo':short,
    'owner':owner,
    'stars':stars,
    'tag':tag,
    'taglabel':taglabel,
  })
Path('/app/poster/top20_latex.json').write_text(json.dumps(lines,indent=2))
